function evaluationPublishCategorySummary_(category) {
  evaluationAssertOperator_(false);
  return evaluationRunTransaction_(function (transaction) {
    const fields = evaluationCategoryFields_(category), runtime = evaluationGet_('evaluationRuntime', 'state', transaction);
    if (!runtime || !Number.isInteger(runtime[fields.revision])) return {writes: [], result: {status: 'PENDING', reason: 'Categoria ainda não reconciliada.'}};
    const reference = evaluationGet_('evaluationReference', 'team', transaction);
    function incomplete(reason) {
      const refPatch = {}; refPatch[fields.status] = 'PENDING'; refPatch[fields.prefix + 'Reason'] = reason;
      const statePatch = {}; statePatch[fields.dirty] = true;
      return {writes: [evaluationWrite_('evaluationReference', 'team', refPatch, reference, ['updatedAt']),
        evaluationWrite_('evaluationRuntime', 'state', statePatch, runtime, ['updatedAt'])], result: {status: 'PENDING', category: category, reason: reason}};
    }
    const profiles = evaluationQuery_('users', [firestoreFilter_('active', 'EQUAL', {booleanValue: true}), firestoreFilter_('access', 'EQUAL', {booleanValue: true})], [], SAHMT_V2_EVALUATION_LEDGER.maxUsers + 1, ['uid', 'active', 'access'], transaction);
    if (profiles.length > SAHMT_V2_EVALUATION_LEDGER.maxUsers) return incomplete('Recálculo incompleto: orçamento seguro excedido.');
    const eligibilityField = fields.prefix + 'EligibilityFingerprint';
    const eligibilityFingerprint = sha256Hex_(JSON.stringify(profiles.map(function (profile) { return [profile.id, profile.uid]; }).sort(function (a, b) { return a[0].localeCompare(b[0]); })));
    if (runtime[fields.dirty] === false && runtime[eligibilityField] === eligibilityFingerprint && reference && reference[fields.status] === 'CONFIRMED' && reference[fields.revision] === runtime[fields.revision]) {
      return {writes: [], result: {status: 'DUPLICATE', category: category, revision: runtime[fields.revision]}};
    }
    const awards = evaluationQuery_('evaluationAwards', [firestoreFilter_('category', 'EQUAL', {stringValue: category})], [], SAHMT_V2_EVALUATION_LEDGER.maxAwards + 1, ['uid', 'category', 'points'], transaction);
    if (profiles.length > SAHMT_V2_EVALUATION_LEDGER.maxUsers || awards.length > SAHMT_V2_EVALUATION_LEDGER.maxAwards) return incomplete('Recálculo incompleto: orçamento seguro excedido.');
    let summary;
    try { summary = evaluationSummarizeCategory_(category, profiles, awards); } catch (error) { return incomplete(String(error.message).slice(0, 300)); }
    const revision = runtime[fields.revision] + (runtime[eligibilityField] && runtime[eligibilityField] !== eligibilityFingerprint ? 1 : 0), writes = [];
    Object.keys(summary.totals).forEach(function (uid) {
      const previous = evaluationGet_('evaluationSummaries', uid, transaction), changes = {uid: uid, status: 'CONFIRMED'};
      changes[fields.total] = summary.totals[uid].total; changes[fields.count] = summary.totals[uid].count; changes[fields.revision] = revision;
      writes.push(evaluationWrite_('evaluationSummaries', uid, changes, previous, ['confirmedAt']));
    });
    const refPatch = {}; refPatch[fields.revision] = revision; refPatch[fields.status] = 'CONFIRMED'; refPatch[fields.prefix + 'Reason'] = '';
    if (category === 'PERFORMANCE') { refPatch.maxPerformance = summary.maxPerformance; refPatch.eligibleCount = summary.eligibleCount; refPatch.allZero = summary.allZero; }
    writes.push(evaluationWrite_('evaluationReference', 'team', refPatch, reference, ['updatedAt']));
    const statePatch = {}; statePatch[fields.dirty] = false; statePatch[fields.revision] = revision; statePatch[eligibilityField] = eligibilityFingerprint;
    writes.push(evaluationWrite_('evaluationRuntime', 'state', statePatch, runtime, ['updatedAt']));
    return {writes: writes, result: {status: 'CONFIRMED', category: category, revision: revision, summaries: Object.keys(summary.totals).length}};
  });
}

function listPendingChecklistSignatureRequests_() {
  const body = {structuredQuery: {
    from: [{collectionId: 'checklistSignatureRequests'}],
    where: {fieldFilter: {field: {fieldPath: 'status'}, op: 'EQUAL', value: {stringValue: 'PENDING_VALIDATION'}}},
    select: {fields: ['id', 'day', 'revision', 'signerUid', 'declaration', 'status', 'justification'].map(function (fieldPath) {
      return {fieldPath: fieldPath};
    })},
    limit: SAHMT_V2_CHECKLIST_VALIDATION.maxPendingPerRun
  }};
  const response = firestoreRequest_(firestoreDocumentsUrl_(':runQuery'), {
    method: 'post', contentType: 'application/json', payload: JSON.stringify(body)
  });
  return (Array.isArray(response) ? response : []).filter(function (item) { return item.document; }).map(function (item) {
    const document = item.document;
    const fields = firestoreFieldsToJs_(document.fields || {});
    return Object.assign(fields, {name: document.name, updateTime: document.updateTime});
  });
}

function readTrustedChecklistSnapshot_(day, transaction) {
  if (day !== checklistSaoPauloDay_()) throw new Error('O pedido não corresponde ao dia atual em São Paulo.');
  const getTrusted = function (collectionId, id, fields) { return transaction ? evaluationGet_(collectionId, id, transaction) : getFirestoreDocument_(collectionId, id, fields); };
  const queryTrusted = function (collectionId, filters, order, maximum, fields) { return transaction ? evaluationQuery_(collectionId, filters, order, maximum, fields, transaction) : queryFirestore_(collectionId, filters, order, maximum, fields); };
  const schedule = getTrusted('scheduleDays', day, ['positions', 'vacationLabel']);
  if (!schedule) throw new Error('Escala do dia indisponível.');
  const stations = queryTrusted('stations', [
    firestoreFilter_('active', 'EQUAL', {booleanValue: true})
  ], [{fieldPath: 'order', direction: 'ASCENDING'}], SAHMT_V2_CHECKLIST_VALIDATION.maxStations + 1,
  ['active', 'start', 'end', 'order', 'name']);
  const vacations = queryTrusted('vacations', [
    firestoreFilter_('active', 'EQUAL', {booleanValue: true}),
    firestoreFilter_('start', 'LESS_THAN_OR_EQUAL', {stringValue: day}),
    firestoreFilter_('end', 'GREATER_THAN_OR_EQUAL', {stringValue: day})
  ], [{fieldPath: 'start', direction: 'ASCENDING'}], 101, ['active', 'start', 'end', 'siglas', 'label']);
  const events = queryTrusted('events', [
    firestoreFilter_('active', 'EQUAL', {booleanValue: true}),
    firestoreFilter_('date', 'EQUAL', {stringValue: day})
  ], [], 201, ['active', 'date', 'eventType', 'memberStatus', 'substitute']);
  const contacts = queryTrusted('contacts', [
    firestoreFilter_('active', 'EQUAL', {booleanValue: true})
  ], [], 201, ['active', 'sigla', 'name']);
  const records = queryTrusted('checklists', [
    firestoreFilter_('date', 'EQUAL', {stringValue: day})
  ], [{fieldPath: 'createdAt', direction: 'DESCENDING'}], SAHMT_V2_CHECKLIST_VALIDATION.maxDailyRecords + 1,
  ['date', 'createdAt', 'stationId', 'condition', 'occurrence']);
  if (stations.length > SAHMT_V2_CHECKLIST_VALIDATION.maxStations || vacations.length > 100 || events.length > 200 ||
      contacts.length > 200 || records.length > SAHMT_V2_CHECKLIST_VALIDATION.maxDailyRecords) {
    throw new Error('O volume excede os limites seguros de validação.');
  }
  const activeStations = stations.filter(function (station) { return (!station.start || station.start <= day) && (!station.end || station.end >= day); });
  if (!activeStations.length) throw new Error('Não há estações vigentes para o Checklist de hoje.');
  const responseByStation = new Map();
  records.forEach(function (record) {
    if (!responseByStation.has(record.stationId)) responseByStation.set(record.stationId, record);
  });
  const entries = activeStations.map(function (station) {
    const record = responseByStation.get(station.id) || null;
    return {
      stationId: station.id, stationName: station.name || station.id,
      condition: record && record.condition || null, occurrence: record && record.occurrence || '',
      responseId: record && record.id || null,
      responseAt: record && record.createdAt instanceof Date ? record.createdAt.getTime() : null
    };
  });
  const fingerprint = sha256Hex_(JSON.stringify({day: day, entries: entries.map(function (entry) {
    return {stationId: entry.stationId, stationName: entry.stationName, condition: entry.condition,
      occurrence: entry.occurrence, responseId: entry.responseId, responseAt: entry.responseAt};
  })}));
  const selection = selectChecklistResponsible_({schedule: schedule, day: day, vacations: vacations, events: events, contacts: contacts});
  if (!selection.ok) throw new Error(selection.reason);
  const matchedProfiles = queryTrusted('users', [firestoreFilter_('sigla', 'EQUAL', {stringValue: selection.sigla})], [], 2,
    ['uid', 'active', 'access', 'displayName', 'email']);
  if (matchedProfiles.length !== 1 || matchedProfiles[0].active !== true || matchedProfiles[0].access !== true || !matchedProfiles[0].uid ||
      transaction && matchedProfiles[0].uid !== matchedProfiles[0].id) {
    throw new Error('Não há perfil ativo e único para a sigla responsável ' + selection.sigla + '.');
  }
  const contactMatches = contacts.filter(function (contact) { return normalizeChecklistText_(contact.sigla) === selection.sigla; });
  const responsibleContact = contactMatches.length === 1
    ? getTrusted('contacts', contactMatches[0].id, ['name', 'email'])
    : null;
  const responsible = {
    responsibleUid: matchedProfiles[0].uid,
    responsibleName: responsibleContact ? responsibleContact.name : matchedProfiles[0].displayName,
    responsibleEmail: responsibleContact ? responsibleContact.email || '' : matchedProfiles[0].email || '',
    position: selection.position, sigla: selection.sigla
  };
  const trustedSnapshot = {date: day, responsibleUid: responsible.responsibleUid,
    responsibleName: responsible.responsibleName, responsibleEmail: responsible.responsibleEmail,
    position: responsible.position, sigla: responsible.sigla, entries: entries};
  return {fingerprint: fingerprint, revision: sha256Hex_(JSON.stringify(trustedSnapshot)),
    snapshot: trustedSnapshot, responsible: responsible, missing: entries.filter(function (entry) { return !entry.condition; }).length};
}

function validateChecklistSignatureRequest_(request) {
  evaluationAssertOperator_(true);
  return evaluationRunTransaction_(function (transaction) {
    const current = evaluationGet_('checklistSignatureRequests', request.id, transaction);
    if (!current || current.status !== 'PENDING_VALIDATION') return {writes: [], result: 'DUPLICATE'};
    function reject(status, message) {
      return {writes: [evaluationWrite_('checklistSignatureRequests', current.id, {status: status, validationMessage: message}, current, ['validatedAt'])], result: status};
    }
    if (!current.day || !/^[a-f0-9]{64}$/.test(current.revision || '') || !current.signerUid ||
        current.id !== current.day + '_' + current.revision + '_' + current.signerUid || current.declaration !== true ||
        String(current.justification || '').trim().length < 8 || String(current.justification || '').length > 500) {
      return reject('REJECTED', 'Solicitação fora do contrato.');
    }
    const signer = evaluationGet_('users', current.signerUid, transaction);
    if (!evaluationActiveProfile_(signer, current.signerUid) || !hasChecklistSignPermission_(signer)) {
      return reject('REJECTED', 'Perfil do solicitante inativo ou sem permissão atual.');
    }
    let snapshot;
    try { snapshot = readTrustedChecklistSnapshot_(current.day, transaction); }
    catch (error) {
      if (error.status) throw error;
      return reject('NEEDS_REVIEW', String(error && error.message || 'Dados indisponíveis para validar.').slice(0, 300));
    }
    const projection = evaluationGet_('checklistResponsibilities', current.day, transaction);
    const projectionWrite = checklistResponsibilityProjectionWrite_(current.day, snapshot, projection);
    if (snapshot.fingerprint !== current.revision) {
      const result = reject('STALE', 'O Checklist mudou depois do pedido. Atualize e solicite nova revisão.');
      result.writes.push(projectionWrite); return result;
    }
    const signatureId = current.day + '_' + snapshot.revision;
    const existing = evaluationGet_('checklistSignatures', signatureId, transaction);
    if (existing) return {writes: [projectionWrite, evaluationWrite_('checklistSignatureRequests', current.id, {
      status: 'DUPLICATE', finalSignatureId: signatureId, pointsAwarded: 0, responsibleAdjustment: 0,
      validationMessage: 'Esta revisão já possui assinatura válida.'
    }, current, ['validatedAt'])], result: 'DUPLICATE'};
    const signature = {
      id: signatureId, date: current.day, checklistId: current.day,
      responsibleUid: snapshot.responsible.responsibleUid, responsibleName: snapshot.responsible.responsibleName,
      responsibleEmail: snapshot.responsible.responsibleEmail,
      signerUid: current.signerUid, signerName: signer.displayName || '', signerEmail: signer.email || '',
      declaration: true, revision: snapshot.revision, snapshot: snapshot.snapshot,
      missing: snapshot.missing, justification: current.justification
    };
    let transfer;
    try { transfer = evaluationApplyChecklistTransfer_(current.day, snapshot.responsible.responsibleUid, current.signerUid, signatureId, {transaction: transaction}); }
    catch (error) {
      if (error.status) throw error;
      return reject('NEEDS_REVIEW', String(error && error.message || 'Pontuação pendente de revisão.').slice(0, 300));
    }
    const applied = transfer.status === 'APPLIED' && snapshot.responsible.responsibleUid !== current.signerUid;
    transfer.writes.push(evaluationWrite_('checklistSignatures', signatureId, signature, null, ['signedAt']));
    transfer.writes.push(projectionWrite);
    transfer.writes.push(evaluationWrite_('checklistSignatureRequests', current.id, {
      status: 'VALIDATED', finalSignatureId: signatureId, pointsAwarded: applied ? 1 : 0,
      responsibleAdjustment: applied ? -1 : 0, evaluationStatus: transfer.status, validationMessage: ''
    }, current, ['validatedAt']));
    return {writes: transfer.writes, result: 'VALIDATED'};
  });
}

function setupSahmtV2Reporting() {
  const properties = sahmtV2Properties_();
  const folder = sahmtV2RequirePrivateFolder_();
  if (properties.getProperty(SAHMT_V2_CONFIG.destinationApprovalProperty) !== 'YES') {
    throw new Error('Antes da configuração, confirme que a pasta oficial de relatórios tem acesso restrito e defina SAHMT_V2_REPORTS_DESTINATION_APPROVED=YES nas propriedades do script.');
  }

  let spreadsheetId = properties.getProperty(SAHMT_V2_CONFIG.reportsSpreadsheetProperty);
  let spreadsheet;
  if (spreadsheetId) {
    sahmtV2RequirePrivateSpreadsheet_(spreadsheetId);
    spreadsheet = SpreadsheetApp.openById(spreadsheetId);
  } else {
    const existingFile = sahmtV2FindExistingReportsSpreadsheet_(folder);
    if (existingFile) {
      spreadsheetId = existingFile.getId();
      sahmtV2RequirePrivateSpreadsheet_(spreadsheetId);
      spreadsheet = SpreadsheetApp.openById(spreadsheetId);
    } else {
      spreadsheet = SpreadsheetApp.create('SAHMT V2.0 - BASE DE RELATÓRIOS');
      DriveApp.getFileById(spreadsheet.getId()).moveTo(folder);
      spreadsheetId = spreadsheet.getId();
      sahmtV2RequirePrivateSpreadsheet_(spreadsheetId);
    }
  }

  const tabConfigs = Object.keys(SAHMT_V2_REPORT_TABS).map(function (name) {
    return {name: name, fields: SAHMT_V2_REPORT_TABS[name].fields};
  });
  // Validate every existing destination tab before changing any tab.
  tabConfigs.forEach(function (config) {
    const existingSheet = spreadsheet.getSheetByName(config.name);
    if (!existingSheet) return;
    const existingHeaders = existingSheet.getRange(1, 1, 1, Math.max(1, existingSheet.getLastColumn())).getValues()[0];
    const hasExistingHeaders = existingSheet.getLastRow() > 0 && existingHeaders.some(function (value) { return String(value || '').trim() !== ''; });
    if (hasExistingHeaders && existingHeaders.join('\u001f') !== config.fields.join('\u001f')) {
      throw new Error('A aba ' + config.name + ' já possui cabeçalhos diferentes do contrato V2; nenhuma aba foi alterada.');
    }
  });
  tabConfigs.forEach(function (config, index) {
    let sheet = spreadsheet.getSheetByName(config.name);
    if (!sheet && index === 0 && spreadsheet.getSheets().length === 1 && spreadsheet.getSheets()[0].getLastRow() === 0) {
      sheet = spreadsheet.getSheets()[0].setName(config.name);
    }
    if (!sheet) sheet = spreadsheet.insertSheet(config.name);
    sheet.getRange(1, 1, 1, config.fields.length).setValues([config.fields]);
    sheet.setFrozenRows(1);
    sheet.getRange(1, 1, 1, config.fields.length).setFontWeight('bold').setBackground('#0d3257').setFontColor('#ffffff');
    if (!sheet.getFilter()) sheet.getRange(1, 1, sheet.getMaxRows(), config.fields.length).createFilter();
    applyReportColumnFormats_(sheet, config);
  });

  properties.setProperty(SAHMT_V2_CONFIG.reportsSpreadsheetProperty, spreadsheetId);

  return {spreadsheetId: spreadsheetId, tabs: tabConfigs.map(function (config) { return config.name; })};
}

function syncSparkReportsPeriodically() {
  const lock = LockService.getScriptLock();
  if (!lock.tryLock(1000)) return {skipped: 'another run holds the lock'};
  try {
    const spreadsheetId = sahmtV2SpreadsheetId_();
    sahmtV2RequirePrivateSpreadsheet_(spreadsheetId);
    const spreadsheet = SpreadsheetApp.openById(spreadsheetId);
    requireSparkReportTabs_(spreadsheet);
    const properties = sahmtV2Properties_();
    const configs = SAHMT_V2_SPARK_REPORT_SCAN.resources;
    const start = Number(properties.getProperty(SAHMT_V2_SPARK_REPORT_SCAN.rotationProperty) || 0) % configs.length;
    const result = {processed: 0, resourcesScanned: 0};
    const pending = [];
    for (let offset = 0; offset < SAHMT_V2_SPARK_REPORT_SCAN.resourcesPerRun; offset++) {
      const config = configs[(start + offset) % configs.length];
      const documents = listSparkReportChanges_(config, SAHMT_V2_SPARK_REPORT_SCAN.recordsPerResource);
      result.resourcesScanned++;
      for (const document of documents) {
        pending.push({config: config, document: document, job: {
          resourceType: config.type,
          resourceId: document.id,
          operation: 'upsert',
          version: Number(document.version) || 1
        }});
        result.processed++;
      }
    }
    upsertSparkReportRows_(spreadsheet, pending);
    // Advance cursors only after every report row has been written successfully.
    // A retry after a partial cursor save is safe because row keys are idempotent.
    pending.forEach(function (item) { saveSparkReportCursor_(item.config, item.document); });
    properties.setProperty(SAHMT_V2_SPARK_REPORT_SCAN.rotationProperty, String((start + SAHMT_V2_SPARK_REPORT_SCAN.resourcesPerRun) % configs.length));
    return result;
  } finally {
    lock.releaseLock();
  }
}

function installSahmtV2SparkReportTrigger() {
  const spreadsheetId = sahmtV2SpreadsheetId_();
  sahmtV2RequirePrivateSpreadsheet_(spreadsheetId);
  requireSparkReportTabs_(SpreadsheetApp.openById(spreadsheetId));
  // Probe the direct collection scan before creating recurring work.
  listSparkReportChanges_(SAHMT_V2_SPARK_REPORT_SCAN.resources[0], 1);
  const existing = ScriptApp.getProjectTriggers().filter(function (trigger) {
    return trigger.getHandlerFunction() === 'syncSparkReportsPeriodically';
  });
  if (!existing.length) ScriptApp.newTrigger('syncSparkReportsPeriodically').timeBased().everyMinutes(5).create();
  return {installed: true, existing: existing.length > 0};
}

function evaluationGet_(collectionId, documentId, transaction) {
  if (!transaction) {
    const result = getFirestoreDocument_(collectionId, documentId);
    return result ? Object.assign(result, {_name: result._documentName}) : null;
  }
  const response = firestoreRequest_(firestoreDocumentsUrl_(':batchGet'), {method: 'post', contentType: 'application/json',
    payload: JSON.stringify({documents: [firestoreDocumentName_(collectionId, documentId)], transaction: transaction})});
  const document = (Array.isArray(response) ? response : [response]).find(function (item) { return item.found; });
  if (!document) return null;
  return evaluationDocument_(document.found);
}

function evaluationPlanAward_(previous, input, options) {
  options = options || {};
  const id = input.id || evaluationAwardId_(input);
  const category = evaluationCategoryFields_(input.category);
  const allowed = input.category === 'PERFORMANCE' ? ['ACKNOWLEDGEMENT', 'SUGGESTION', 'TEST', 'CHECKLIST'] : ['MATERIAL', 'QUESTIONS'];
  if (!allowed.includes(input.modality) || !evaluationValidPoints_(input.points)) throw new Error('Modalidade ou pontuação inválida.');
  if (!options.correction) {
    const defaults = {ACKNOWLEDGEMENT: [0, 1], SUGGESTION: [0, 2], MATERIAL: [0, 1], QUESTIONS: [0, 1], CHECKLIST: [-1, 0, 1]};
    if (defaults[input.modality] && !defaults[input.modality].includes(input.points)) throw new Error('Pontuação fora da regra da modalidade.');
    if (input.modality === 'TEST' && (input.points < 0 || !Number.isFinite(input.maxTestScore) || input.maxTestScore < input.points)) throw new Error('Nota corrigida ou máximo não confirmado.');
  }
  if (previous && (previous.uid !== input.uid || previous.category !== input.category || previous.modality !== input.modality ||
      previous.creditScopeId !== input.creditScopeId || String(previous.version) !== String(input.version))) throw new Error('A identidade imutável do crédito não corresponde à fonte.');
  if (previous && (!evaluationValidPoints_(previous.points) || !Number.isInteger(previous.awardVersion) || previous.awardVersion < 1)) throw new Error('Estado do crédito inconsistente.');
  if (options.correction && (!previous || options.expectedAwardVersion !== previous.awardVersion || String(input.reason || '').trim().length < 8)) throw new Error('Correção desatualizada ou sem justificativa.');
  if (previous && previous.adminOverride === true && !options.correction && input.points !== previous.points) {
    return {status: 'NEEDS_REVIEW', awardId: id, awardVersion: previous.awardVersion, points: previous.points, changed: false, categoryFields: category};
  }
  if (previous && input.points === previous.points && (previous.adminOverride === true && !options.correction ||
      previous.sourceFingerprint === input.sourceFingerprint && !options.correction && !options.forceAudit)) {
    return {status: 'DUPLICATE', awardId: id, awardVersion: previous.awardVersion, points: previous.points, changed: false, categoryFields: category};
  }
  const awardVersion = previous ? previous.awardVersion + 1 : 1;
  const pointsBefore = previous ? previous.points : 0;
  const originalPoints = previous ? previous.originalPoints : input.points;
  const award = Object.assign({}, previous ? evaluationClean_(previous) : {}, evaluationClean_(input), {
    id: id, awardVersion: awardVersion, originalPoints: originalPoints,
    adminOverride: options.correction ? true : previous ? previous.adminOverride === true : false,
    lastLedgerId: id + '-v' + awardVersion
  });
  const ledger = {
    id: award.lastLedgerId, awardId: id, uid: input.uid, category: input.category, modality: input.modality,
    activityId: input.activityId || '', areaId: input.areaId || '', version: input.version,
    creditScopeId: input.creditScopeId, points: input.points - pointsBefore, originalPoints: originalPoints,
    correctedPoints: input.points, pointsBefore: pointsBefore, correctsId: previous ? previous.lastLedgerId || '' : '',
    transferId: input.transferId || '', sourceType: input.sourceType || '', sourceId: input.sourceId || '',
    evidence: input.evidence || {}, approvedByUid: input.approvedByUid || '', reason: String(input.reason || '').trim(),
    awardVersion: awardVersion
  };
  return {status: 'APPLIED', awardId: id, awardVersion: awardVersion, points: input.points, changed: true, award: award, ledger: ledger, categoryFields: category};
}

function evaluationQuery_(collectionId, filters, orderBy, maximum, fieldPaths, transaction, cursor) {
  const query = {from: [{collectionId: collectionId}], limit: maximum || 100};
  filters = filters || []; orderBy = orderBy || [];
  if (filters.length === 1) query.where = {fieldFilter: filters[0]};
  if (filters.length > 1) query.where = {compositeFilter: {op: 'AND', filters: filters.map(function (filter) { return {fieldFilter: filter}; })}};
  if (orderBy.length) query.orderBy = orderBy.map(function (item) { return {field: {fieldPath: item.fieldPath}, direction: item.direction}; });
  if (fieldPaths && fieldPaths.length) query.select = {fields: fieldPaths.map(function (field) { return {fieldPath: field}; })};
  if (cursor) query.startAt = cursor;
  const body = {structuredQuery: query}; if (transaction) body.transaction = transaction;
  const response = firestoreRequest_(firestoreDocumentsUrl_(':runQuery'), {method: 'post', contentType: 'application/json', payload: JSON.stringify(body)});
  return (Array.isArray(response) ? response : []).filter(function (item) { return item.document; }).map(function (item) { return evaluationDocument_(item.document); });
}

function evaluationRunTransaction_(callback) {
  for (let attempt = 0; attempt < SAHMT_V2_EVALUATION_LEDGER.maxAttempts; attempt++) {
    const started = firestoreRequest_(firestoreDocumentsUrl_(':beginTransaction'), {method: 'post', contentType: 'application/json', payload: '{}'});
    try {
      const planned = callback(started.transaction);
      if (!planned || !Array.isArray(planned.writes) || planned.writes.length > SAHMT_V2_EVALUATION_LEDGER.maxWrites) throw new Error('O commit excede o orçamento seguro ou não foi planejado.');
      firestoreRequest_(firestoreDocumentsUrl_(':commit'), {method: 'post', contentType: 'application/json', payload: JSON.stringify({transaction: started.transaction, writes: planned.writes})});
      return planned.result;
    } catch (error) {
      try { firestoreRequest_(firestoreDocumentsUrl_(':rollback'), {method: 'post', contentType: 'application/json', payload: JSON.stringify({transaction: started.transaction})}); } catch (_) {}
      if ((error.status !== 409 && error.status !== 412) || attempt + 1 === SAHMT_V2_EVALUATION_LEDGER.maxAttempts) throw error;
    }
  }
}

function evaluationWrite_(collectionId, documentId, changes, previous, serverTimeFields) {
  const fields = evaluationClean_(changes);
  (serverTimeFields || []).forEach(function (field) { delete fields[field]; });
  const write = {update: {name: firestoreDocumentName_(collectionId, documentId), fields: firestoreFieldsFromJs_(fields)},
    currentDocument: previous ? previous._updateTime ? {updateTime: previous._updateTime} : previous : {exists: false}};
  if (previous && previous.exists !== false) write.updateMask = {fieldPaths: Object.keys(fields)};
  if (serverTimeFields && serverTimeFields.length) write.updateTransforms = serverTimeFields.map(function (field) { return {fieldPath: field, setToServerValue: 'REQUEST_TIME'}; });
  return write;
}

