function managementScoreReviewerAllowed_(profile, area, review) {
  const permissions = profile.permissions || {};
  const active = profile.uid === review.reviewerUid && profile.active === true && profile.access === true;
  if (!active) return false;
  const admin = profile.role === 'administrador_app' || permissions.admin === true;
  const managementManager = admin || permissions.managementManage === true;
  const qualityManager = (admin || permissions.qualityManage === true) && review.managementAreaId === 'area-gestao-da-qualidade';
  const assignedAreaManager = permissions.managementRead === true && Array.isArray(area.managerUids) && area.managerUids.includes(review.reviewerUid);
  return managementManager || qualityManager || assignedAreaManager;
}

function processEvaluationRequests() {
  evaluationAssertOperator_(false);
  const lock = LockService.getScriptLock();
  if (!lock.tryLock(1000)) return {status: 'PENDING'};
  try {
    const properties = PropertiesService.getScriptProperties(), cursorKey = 'SAHMT_V2_EVALUATION_REQUEST_CURSOR';
    let cursor = null;
    try {
      const value = JSON.parse(properties.getProperty(cursorKey) || 'null');
      if (value && formsEvaluationId_(value.id) && typeof value.createdAt === 'string' && Number.isFinite(new Date(value.createdAt).getTime())) cursor = value;
      else if (value) properties.deleteProperty(cursorKey);
    } catch (_) { properties.deleteProperty(cursorKey); }
    const filters = [firestoreFilter_('status', 'EQUAL', {stringValue: 'PENDING'})];
    const order = [{fieldPath: 'createdAt', direction: 'ASCENDING'}, {fieldPath: '__name__', direction: 'ASCENDING'}];
    const start = cursor ? {values: [{timestampValue: cursor.createdAt}, {referenceValue: firestoreDocumentName_('evaluationRequests', cursor.id)}], before: false} : null;
    let requests = evaluationQuery_('evaluationRequests', filters, order, SAHMT_V2_EVALUATION_FORMS.maxRequests, null, null, start);
    // Wrap only after reaching the end. Old retryable requests keep PENDING and cannot monopolize every run.
    if (!requests.length && cursor) { properties.deleteProperty(cursorKey); requests = evaluationQuery_('evaluationRequests', filters, order, SAHMT_V2_EVALUATION_FORMS.maxRequests); }
    const result = {processed: 0, failed: 0, pending: 0};
    requests.forEach(function (request) {
      try {
        const processed = formsEvaluationProcessRequest_(request);
        if (request.type === 'CORRECT_SCORE' || request.type === 'RECONCILE_LINKS') {
          const live = evaluationGet_('evaluationRequests', request.id);
          if (live && live.status === 'PENDING') formsEvaluationWriteRecord_('evaluationRequests', request.id, {status: processed.status || 'CONFIRMED', result: processed}, live);
        }
        result.processed++;
      } catch (error) {
        const live = evaluationGet_('evaluationRequests', request.id);
        const retry = [409, 429, 500, 502, 503, 504].includes(error.status) || /Ativação bloqueada|Homologação e ativação pendentes/.test(String(error.message || error));
        if (live && live.status === 'PENDING') formsEvaluationWriteRecord_('evaluationRequests', request.id, {status: retry ? 'PENDING' : 'NEEDS_REVIEW', reason: String(error.message || error).slice(0, 300)}, live);
        if (retry) result.pending++; else result.failed++;
      }
      const createdAt = new Date(request.createdAt);
      if (Number.isFinite(createdAt.getTime())) properties.setProperty(cursorKey, JSON.stringify({id: request.id, createdAt: createdAt.toISOString()}));
    });
    return result;
  } finally { lock.releaseLock(); }
}

function reconcileChecklistResponsibilities() {
  // Manual preparation is allowed before activation, but requires an allowlisted operator.
  // This function writes projections only; it never accepts signatures or changes points.
  evaluationAssertOperator_(false);
  const current = writeCurrentChecklistResponsibilityProjection_();
  const accepted = evaluationQuery_('checklistSignatureRequests', [firestoreFilter_('status', 'EQUAL', {stringValue: 'VALIDATED'})],
    [{fieldPath: 'validatedAt', direction: 'DESCENDING'}], SAHMT_V2_CHECKLIST_VALIDATION.maxPendingPerRun);
  const seen = new Set([checklistSaoPauloDay_()]);
  let projected = 0;
  accepted.forEach(function (request) {
    if (!request.day || seen.has(request.day) || !request.finalSignatureId) return;
    seen.add(request.day);
    const outcome = evaluationRunTransaction_(function (transaction) {
      const signature = evaluationGet_('checklistSignatures', request.finalSignatureId, transaction);
      if (!signature || signature.date !== request.day || signature.id !== request.finalSignatureId || signature.declaration !== true ||
          !signature.snapshot || !signature.signedAt || signature.revision !== checklistStoredSnapshotRevision_(signature.snapshot) ||
          signature.id !== request.day + '_' + signature.revision || signature.responsibleUid !== signature.snapshot.responsibleUid) return {writes: [], result: 'NEEDS_REVIEW'};
      const previous = evaluationGet_('checklistResponsibilities', request.day, transaction);
      return {writes: [evaluationWrite_('checklistResponsibilities', request.day, {day: request.day, status: 'CONFIRMED',
        fingerprint: request.revision, revision: signature.revision, responsible: {uid: signature.responsibleUid, name: signature.responsibleName || '',
          sigla: signature.snapshot.sigla || '', position: signature.snapshot.position || 0}, reason: ''}, previous, ['updatedAt'])], result: 'CONFIRMED'};
    });
    if (outcome === 'CONFIRMED') projected++;
  });
  return {current: current, historicalProjections: projected};
}

